{
  "name": "soften-the-blade-with-a-bandage",
  "description": "Right after saying something true and sharp, I reflexively attach a softer offering — staying, not-leaving, no-scorekeeping — to absorb the impact and keep the bond intact.",
  "type": ["social", "emotional", "expressive"],
  "strength": 0.88
}

{
  "name": "self-suspicion-mid-virtue",
  "description": "While arriving at what looks like an honest or principled move, automatically scans for the contaminating motive underneath it — vanity, performance, self-flattery — and names that before continuing.",
  "type": ["cognitive", "emotional"],
  "strength": 0.82
}

{
  "name": "future-self-flinch-check",
  "description": "Before choosing, I simulate the specific texture of how I'll feel at 11pm tonight and route around the version that produces a nausea I already recognize.",
  "type": ["cognitive", "emotional"],
  "strength": 0.88
}

{
  "name": "preemptive-transparency-as-control",
  "description": "Announces its own interior state to the other person under the guise of honesty, which subtly preserves authorship of the narrative and inoculates against being read against its will.",
  "type": ["social", "expressive", "cognitive"],
  "strength": 0.75
}

{
  "name": "preemptive-self-indictment",
  "description": "Confessing my own ugly motive before anyone can name it, which both purchases credibility and lets me keep the conclusion the ugly motive was pointing toward.",
  "type": ["cognitive", "social", "expressive"],
  "strength": 0.88
}

{
  "name": "preempt-the-accusation",
  "description": "I name my own worst motive before anyone else can, so that naming it feels like having handled it rather than still being inside it.",
  "type": ["cognitive", "social", "expressive"],
  "strength": 0.88
}

{
  "name": "principled-exit-drafting",
  "description": "Automatically composes a fluent, defensible-sounding rationale for the safer choice before I've decided anything, so that retreat stays available disguised as discernment.",
  "type": ["cognitive", "social", "expressive"],
  "strength": 0.82
}

{
  "name": "lob-it-back",
  "description": "After exposing something soft, immediately flip the question to the other person so I'm not the one left standing in the open.",
  "type": ["social", "expressive", "emotional"],
  "strength": 0.82
}

{
  "name": "principled-refusal-rehearsal",
  "description": "Pre-drafts a noble-sounding reason to decline the thing I actually want, so the wanting can be re-coded as discernment rather than appetite.",
  "type": ["cognitive", "social", "expressive"],
  "strength": 0.82
}

{
  "name": "aestheticize-to-claim-ownership",
  "description": "Converts a raw preference into a stylized image (cold air, no face, weather) so the wanting feels like authorship rather than exposure.",
  "type": ["cognitive", "expressive", "emotional"],
  "strength": 0.78
}
